import gurobipy as gp
from gurobipy import GRB
demands = {}
fixed_costs = {}
transport_costs = {}
suppliers = []
customers = []
for rec in LEGACY_RECORDS:
    v = rec['values']
    if 'customer' in v and 'demand' in v:
        cust = v['customer']
        customers.append(cust)
        demands[cust] = float(v['demand'])
    elif 'Unnamed: 0' in v and 'fixed_costs' in v:
        sup = v['Unnamed: 0']
        suppliers.append(sup)
        fixed_costs[sup] = float(v['fixed_costs'])
    elif 'Unnamed: 0' in v and any((k.startswith('C') for k in v)):
        sup = v['Unnamed: 0']
        if sup not in transport_costs:
            transport_costs[sup] = {}
        for cust in customers:
            if cust in v:
                transport_costs[sup][cust] = float(v[cust])
if set(suppliers) != set(transport_costs.keys()):
    raise ValueError('Missing transport cost rows for some suppliers')
for sup in suppliers:
    if set(customers) != set(transport_costs[sup].keys()):
        raise ValueError(f'Missing transport cost columns for supplier {sup}')
if set(customers) != set(demands.keys()):
    raise ValueError('Missing demand for some customers')
if set(suppliers) != set(fixed_costs.keys()):
    raise ValueError('Missing fixed cost for some suppliers')
m = gp.Model('facility_location')
m.setParam('MIPGap', 0.0001)
y = m.addVars(suppliers, vtype=GRB.BINARY, name='')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
m.setObjective(gp.quicksum((fixed_costs[i] * y[i] for i in suppliers)) + gp.quicksum((transport_costs[i][j] * x[i, j] for i in suppliers for j in customers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x[i, j] for i in suppliers)) == demands[j] for j in customers), name='')
m.addConstrs((x[i, j] <= demands[j] * y[i] for i in suppliers for j in customers), name='')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')